def change_base(x: int, base: int):
    """Change numerical base of input number x to base.
    return string representation after the conversion.
    base numbers are less than 10.
    >>> change_base(8, 3)
    '22'
    >>> change_base(8, 2)
    '1000'
    >>> change_base(7, 2)
    '111'
    """
    if x == 0:
        return '0'
    if base == 10:
        return str(x)
    if base == 2:
        return bin(x)[2:]
    if base == 8:
        return oct(x)[2:]
    if base == 16:
        return hex(x)[2:]
    return None

